import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Re_ADOJAS: Chart Player","description":"","frontmatter":{"title":"Re_ADOJAS: Chart Player","order":3},"headers":[],"relativePath":"mods/online-tools/re_adojas.md","filePath":"mods/online-tools/re_adojas.md","lastUpdated":1786957039000}'),i={name:"mods/online-tools/re_adojas.md"};function l(s,e,n,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="re-adojas-chart-player" tabindex="-1">Re_ADOJAS: Chart Player <a class="header-anchor" href="#re-adojas-chart-player" aria-label="Permalink to &quot;Re_ADOJAS: Chart Player&quot;">​</a></h1><p><a href="/tools/re_adojas/">Re_ADOJAS</a> is a lightweight ADOFAI chart player based on <a href="./../../libs/adofai-js/">ADOFAI-JS</a>, supporting multi-platform operation.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Chart loading</strong>: supports <code>.adofai</code>, <code>.json</code>, <code>.zip</code> level files</li><li><strong>Rendering</strong>: WebGL and WebGPU (experimental), Web Worker multi-threaded rendering</li><li><strong>Themes</strong>: Light / Dark / Follow System</li><li><strong>Media import</strong>: audio, video background, decoration images, background images</li><li><strong>Performance</strong>: adjustable target frame rate, sync/async rendering, multiple level loading methods</li><li><strong>Visual effects</strong>: planet trail, hit sounds, chart info indicators (TBPM / CBPM / Map Time / Tiles)</li><li><strong>Other</strong>: fullscreen mode, FPS display, performance monitor panel</li><li><strong>Internationalization</strong>: Simplified Chinese, English, Japanese</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>Open <a href="/tools/re_adojas/">Re_ADOJAS</a></li><li>Load a chart file (you can drag it directly into the window)</li><li>If needed, import audio, video background, and other resources</li><li>Start playback</li></ol><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>For large charts, use Worker or async loading methods</li></ul>',8)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
